import numpy as np


def q464(priors, value_sums, visits, c_puct=1.5):
    n = np.asarray(visits)
    q = np.divide(
        value_sums, n, out=np.zeros_like(n, dtype=float), where=n > 0
    )
    score = q + c_puct * np.asarray(priors) * np.sqrt(max(1, n.sum())) / (
        1 + n
    )
    return (int(score.argmax()), score)
